List<String> ans;
    public List<String> generateParenthesis(int n) {
        ans = new ArrayList<>();
        dfs(n, n, new StringBuilder());
        return ans;
    }

    // l/r：还剩几个左/右括号
    private void dfs(int l, int r, StringBuilder sb) {
        if (l < 0 || r < 0) {
            return;
        }
        if (l == r && l == 0) {
            ans.add(sb.toString());
            return;
        }
        // 剩余左括号比右括号多 ⇒ 已放下的 ')' 已经超过 '('，前缀非法
        if (l > r) {
            return;
        }
        sb.append("(");
        dfs(l - 1, r, sb);
        sb.deleteCharAt(sb.length() - 1);

        sb.append(")");
        dfs(l, r - 1, sb);
        sb.deleteCharAt(sb.length() - 1);
    }

