List<String> ans;
    public List<String> generateParenthesis(int n) {
        ans = new ArrayList<>();
        dfs(n, n, "");
        return ans;
    }

    private void dfs(int left, int right, String sb) {
        if (left < 0 || right < 0) {
            return;
        }
        if (left == right && left == 0) {
            ans.add(sb);
            return;
        }
        if (right < left) {
            return;
        }
        dfs(left - 1, right, sb + "(");

        dfs(left, right - 1, sb + ")");
    }
